#include "ump/KaviroCore.h"
#include <iostream>
int main(int argc,char**argv){using namespace ump;if(argc<2){std::cout<<"KAVIRO Player\n--inspect <file> | --scan <folder> | --engine-info | --version\n";return 0;}std::string a=argv[1];if(a=="--version"){std::cout<<"KAVIRO Player 0.7.1-core-recovery\n";return 0;}if(a=="--engine-info"){auto e=MediaEngineFactory::createBestAvailableEngine();auto i=e->info();std::cout<<i.name<<" standalone="<<i.standalone<<"\n";return 0;}if(a=="--inspect"&&argc>2){auto p=MediaProbe::inspect(argv[2]);if(!p.success){std::cerr<<p.error<<'\n';return 3;}std::cout<<p.format<<" "<<p.codec<<" "<<mediaTypeName(p.type)<<" "<<p.durationMs<<"ms\n";return 0;}if(a=="--scan"&&argc>2){MediaLibrary l;auto x=l.scan(argv[2]);std::cout<<x.size()<<" media files\n";return 0;}return 2;}